<section class="page-head"><div class="container"><div class="eyebrow">ROADMAPS</div><h1>Parcours types</h1><p>Des séquences de certifications indicatives pour aider le Student Service à orienter les étudiants.</p></div></section>
<section class="section"><div class="container timeline"><?php foreach($tracks as $i=>$track): ?><article class="track-card"><div class="track-head"><span class="step">0<?= $i+1 ?></span><div><h2><?= e($track['name']) ?></h2><p><?= e($track['description']) ?></p></div><span class="chip domain-<?= e($track['domain']) ?>"><?= e(domain_label($track['domain'])) ?></span></div><div class="track-certs"><?php foreach($track['certs'] as $j=>$cert): ?><a href="/certification?id=<?= (int)$cert['id'] ?>" class="track-cert"><span><?= str_pad((string)($j+1),2,'0',STR_PAD_LEFT) ?></span><div><b><?= e($cert['name']) ?></b><small><?= e($cert['vendor']) ?> · <?= e(domain_label($cert['domain'])) ?></small></div><span>→</span></a><?php endforeach; ?></div></article><?php endforeach; ?></div></section>
